import{_ as a,o as t,c as r,ak as n}from"./chunks/framework.B8jO0odJ.js";const u=JSON.parse('{"title":"Chainy game design","description":"Historical snapshot taken before v2 adoption on October 23, 2026. Not active requirements or current progress. See the adoption archive.","frontmatter":{"title":"Chainy game design","description":"Historical snapshot taken before v2 adoption on October 23, 2026. Not active requirements or current progress. See the adoption archive.","source":"docs/archive/pre-v2-adoption-2026-10-23/docs/game-design.md","category":"Archive","sourceUpdated":"2026-10-23T16:51:22+08:00","outline":[2,3]},"headers":[],"relativePath":"content/docs/archive/pre-v2-adoption-2026-10-23/docs/game-design.md","filePath":"content/docs/archive/pre-v2-adoption-2026-10-23/docs/game-design.md"}'),o={name:"content/docs/archive/pre-v2-adoption-2026-10-23/docs/game-design.md"};function i(s,e,l,d,c,h){return t(),r("div",null,[...e[0]||(e[0]=[n('<div><h1 id="chainy-game-design">Chainy game design<a class="header-anchor" href="#chainy-game-design" aria-label="Link to this section">​</a></h1><blockquote><p>Historical snapshot taken before v2 adoption on October 23, 2026. Not active requirements or current progress. See the <a href="/Chainy-Docs/content/docs/archive/pre-v2-adoption-2026-10-23/readme.html">adoption archive</a>.</p></blockquote><p>Current gameplay direction, updated October 22, 2026. Based on Christian Jude Villaber&#39;s technical design and the user&#39;s explicit replacement of the earlier plan. The October 22 visual decision establishes the isometric low-poly camera, world treatment and in-world dialogue overlay described below.</p><h2 id="purpose-and-audience">Purpose and audience<a class="header-anchor" href="#purpose-and-audience" aria-label="Link to this section">​</a></h2><p>Chainy introduces foundational Web3, Blockchain and AI concepts through an offline 3D Android game for ages 12–17. Use plain English, visual examples and short explanations. Assume that some players are new to touch controls and the subject matter.</p><p>The game is single-player. Learning about blockchain and AI does not require real cryptocurrency, an online blockchain, or a cloud AI service.</p><h2 id="player-experience">Player experience<a class="header-anchor" href="#player-experience" aria-label="Link to this section">​</a></h2><ol><li>Open the game and create or select a local learner profile.</li><li>Enter a compact isometric learning level and move through the 3D scene.</li><li>Interact with a guide or lesson object. Dialogue appears over the same live 3D world rather than loading a separate dialogue scene.</li><li>Start one Quiz, Wordle or BlockMatch activity.</li><li>Read the result and explanation. Retry according to that activity&#39;s rules.</li><li>Save progress, then continue or leave. Returning players load this device&#39;s saved progress.</li></ol><p>The actual level layout, movement controls and lesson sequence must be agreed by Sherwin and Christian. The previous tappable nine-lesson map is no longer the gameplay specification.</p><h2 id="the-three-mini-games">The three mini-games<a class="header-anchor" href="#the-three-mini-games" aria-label="Link to this section">​</a></h2><table><thead><tr><th>Mode</th><th>Established by the technical design</th><th>Rules still to freeze on CH-02</th><th>Completion check</th></tr></thead><tbody><tr><td>Quiz</td><td>Shows questions, evaluates answers and calculates scores; current UI reads ScriptableObjects</td><td>Approved question set, scoring, pass/completion rule, retry handling</td><td>Correct and incorrect answers produce the expected score and explanation; saved result reloads</td></tr><tr><td>Wordle</td><td>Validates guesses and evaluates letters</td><td>Educational word list and definitions, word length, guess limit, repeated-letter feedback, win/loss/retry rule</td><td>Valid/invalid guesses, repeated letters, win and exhausted attempts behave as agreed</td></tr><tr><td>BlockMatch</td><td>Board operations, matches, cascades and objectives; uses pooled objects</td><td>What counts as a match, learner meaning, board limits, move/time rule, no-move case, cascade/end rule</td><td>Legal/illegal moves, cascade completion, win/loss and no-move handling match the agreed rules</td></tr></tbody></table><p>A familiar puzzle format does not by itself teach a concept. Each activity needs a short learning objective and a result explanation. Word guessing may support vocabulary; matching needs a meaningful relation that the learner can explain. Sean drafts and checks the learning material with Sherwin; Christian checks whether the rule can be implemented as described.</p><p>The user confirmed that exact mini-game rules are not yet agreed. No exact score threshold, board size, dictionary, word length, lesson count or attempt limit is approved by the supplied document. Put those values in one short rules sheet before building content around them.</p><h2 id="levels-camera-characters-and-art">Levels, camera, characters and art<a class="header-anchor" href="#levels-camera-characters-and-art" aria-label="Link to this section">​</a></h2><p>The approved gameplay presentation is a fixed orthographic isometric view with a roughly 35–45 degree top-down angle. The player remains small within a readable, navigable level rather than filling the frame as in a close third-person camera. Paths, stairs, bridges, objectives and interactable guides must remain legible from this view. Foreground geometry must not hide required routes or interaction states.</p><p>Use restrained stylized low-poly art: faceted silhouettes, simple beveled planes, sparse painterly surface detail, angular ruins, water silhouettes, controlled bloom and long readable shadows. The supplied Tunic screenshots are the camera, lighting, material-density and environment-composition reference. They do not authorize copying Tunic&#39;s maps, characters, creatures, props, icons or HUD. Do not use the bright voxel-block diorama treatment or rounded toy-rendered environment from the superseded concepts.</p><p>Retain Chainy&#39;s identity within that treatment: the blue-haired explorer in yellow, the friendly white screen-faced robot and cyan record/block motifs. Character models and portraits should be simplified into the same faceted low-poly language instead of appearing as a separate animated-film style. See the <a href="/Chainy-Docs/content/docs/archive/pre-v2-adoption-2026-10-23/docs/design/design-brief.html">art and UI brief</a>.</p><p><img src="/Chainy-Docs/attachments/docs/media/gdd/current-visuals/isometric-exploration.png" alt="Approved isometric exploration mockup"></p><p><em>Visual target for camera, scene density and interaction scale. Concept mockup, not implementation evidence.</em></p><p>Build and test one representative level before expanding the asset inventory. Reuse the reported controller and useful existing models where they can be adapted without preserving the superseded visual treatment. Level count and art quantity follow the measured effort and Android performance of that sample.</p><h2 id="dialogue-and-learning-choice-overlay">Dialogue and learning-choice overlay<a class="header-anchor" href="#dialogue-and-learning-choice-overlay" aria-label="Link to this section">​</a></h2><p>Dialogue is an overlay on the active isometric gameplay scene. Starting a conversation pauses player movement and prevents world controls from receiving taps until the dialogue closes. The 3D world stays visible behind the interface so the learner keeps spatial context.</p><p>The required composition is:</p><ul><li>a wide dialogue panel along the bottom of the screen, containing the speaker name and current line or question;</li><li>answer or response choices stacked in the middle of the screen above the dialogue panel;</li><li>the Explorer portrait anchored at the left edge and the guide/other speaker portrait anchored at the right edge;</li><li>neutral answer styling before selection, with correctness communicated only after submission through text or icons as well as color; and</li><li>safe margins, readable wrapping and touch targets sized for the smallest supported phone.</li></ul><p>During dialogue, hide or disable the movement joystick and world interaction button. Only the dialogue layer accepts input. Closing or completing the exchange restores gameplay controls and returns focus to the same world state.</p><p><img src="/Chainy-Docs/attachments/docs/media/gdd/current-visuals/dialogue-overlay.png" alt="Approved dialogue overlay mockup"></p><p><em>Layout target: live isometric world, bottom dialogue, centered choices and side portraits. The sample question illustrates placement and does not freeze the full Quiz content or scoring rules.</em></p><h2 id="profiles-results-and-progress">Profiles, results and progress<a class="header-anchor" href="#profiles-results-and-progress" aria-label="Link to this section">​</a></h2><p>A learner code selects a profile stored on that device. It is not an authenticated online account. Switching learners must clear the previous learner&#39;s visible progress before showing the next profile.</p><p>Only one mini-game receives gameplay input at a time. Loading, saving, pause and board resolution must prevent accidental duplicate actions. Show “saved” only after SQLite confirms the write. A save failure offers a retry and must not erase the last good record.</p><p>Christian must settle whether score means latest, best or cumulative score, and whether attempts count guesses, question responses or completed playthroughs. Sean must check that the chosen meaning supports the approved evaluation. See the <a href="/Chainy-Docs/content/docs/archive/pre-v2-adoption-2026-10-23/docs/design/database-schema.html">data reference</a>.</p><h2 id="ui-and-accessibility">UI and accessibility<a class="header-anchor" href="#ui-and-accessibility" aria-label="Link to this section">​</a></h2><p>Miguel provides profile, menu, in-game instructions, the dialogue/choice overlay, Quiz/Wordle/BlockMatch UI, result, pause and save-error screens. Use readable text and generous touch targets. Essential instructions must work with sound off, and feedback must use text or icons as well as color. Show the current objective and available action clearly. The dialogue overlay must preserve the isometric world context and must not become a separate visual-novel scene or a full-screen activity menu.</p><p>The <a href="/Chainy-Docs/content/docs/archive/pre-v2-adoption-2026-10-23/docs/design/app-flow.html">player flow</a> defines navigation and recovery. The <a href="/Chainy-Docs/content/docs/archive/pre-v2-adoption-2026-10-23/docs/qa-evaluation.html">test checklist</a> defines the evidence needed before beta.</p><h2 id="delivery-and-ownership">Delivery and ownership<a class="header-anchor" href="#delivery-and-ownership" aria-label="Link to this section">​</a></h2><p>Sherwin owns learning-game rules and scope; Christian owns implementation and integration; Luis owns art; Sean owns instructional copy and manuscript; Miguel owns UI and supports documentation/testing.</p><p><strong>Fixed beta: November 3–6. Fixed pre-final: November 21, 2026.</strong> First accepted loop: October 18 planning target. Integrated candidate: October 30 planning target. Testing, manuscript work and rehearsal remain in the <a href="/Chainy-Docs/content/docs/archive/pre-v2-adoption-2026-10-23/docs/kanban-plan-draft.html">task plan</a>.</p><p>The old record-ordering activity, three-copy simulation, classifier and grid-agent implementation requirements are withdrawn by the user&#39;s October 12 decision. Their archived specifications are not work to add alongside the three new modes.</p></div>',1)])])}const m=a(o,[["render",i]]);export{u as __pageData,m as default};
